body:
{
  "pains": [
    {
      "id": "pain:half-the-list-bounces",
      "statement": "I pay for the contacts, send to them, and a big chunk of the list bounces straight back.",
      "element": "b2b:functional:product_quality",
      "shape": {
        "surface": "Bounce notifications come back within minutes of the first send, on addresses that were sold as current.",
        "operational": "The next list gets run through a second verification step before anyone will send to it, and the buyer starts treating the vendor's export as raw material rather than a finished list.",
        "personal": null,
        "personal_note": "No source read shows what the bounces cost the individual. The reviews stop at the list and the money; none of them say what happened to the person's number, their week or their standing. Looked in the 1-2 star Trustpilot reviews for ZoomInfo and Seamless.AI and the GetApp Apollo cons, which is where a personal line would sit if it were written down anywhere public."
      },
      "workflow": "The export out of Apollo or ZoomInfo into a CSV, then into the sending tool, at the step a day later when the bounce report comes back and the usable count is nothing like the count that was exported.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "The first campaign sent off a newly bought list, when the bounce reports land and the real size of the list becomes visible for the first time.",
          "cites": ["src:1", "src:7"]
        }
      ],
      "who_feels": ["economic_buyer", "end_user"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "Most emails were non deliverable.",
              "cites": ["src:1"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "On some lists, we might find only 10–20 usable contacts out of 1,000 leads.",
              "cites": ["src:7"]
            }
          ],
          "costs_them": "The spend on the list plus the spend on whatever tool verifies it afterwards, for a usable count the two quotes put far below what was bought.",
          "fears": "That the money already spent has bought a list nobody on the team will trust, and the next renewal is a renewal of the same thing.",
          "dream_outcome": "The contacts they paid for are the contacts that receive the email, with no second tool standing between the export and the send."
        },
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Some emails can bounce or be missing, and the interface can feel a little busy when I only need quick validation.",
              "cites": ["src:4"]
            },
            {
              "situation": "venting",
              "verbatim": "Not happy at all with the contact data I got from ZoomInfo.",
              "cites": ["src:1"]
            }
          ],
          "costs_them": "The validation pass they run before every send, which the first quote describes as the thing they came for and could not get quickly.",
          "fears": "No source read shows the fear. Both quotes stop at the annoyance and neither says what they think happens next.",
          "dream_outcome": "Pull the contact, send to it, and never open a separate checker."
        }
      },
      "segments": ["seg:smb"],
      "feature_ref": "feat:waterfall",
      "feature_note": "Waterfall enrichment is the feature that fills the gap this pain is about. Nothing in the company artifact speaks to what happens after the send, which is where these buyers say they find out.",
      "cites": ["src:1", "src:7", "src:4"]
    },
    {
      "id": "pain:the-record-with-no-number",
      "statement": "The person is in there, but the email or the phone number is not, so the record is no use to me.",
      "element": "b2b:ease_of_doing_business:availability",
      "shape": {
        "surface": "The search returns the right person and the fields that matter are blank.",
        "operational": "They turn on the verified-only filter to strip the blanks out, and one reviewer puts the cost of that at about a fifth of the list.",
        "personal": null,
        "personal_note": "No source read shows the personal rung. The GetApp Apollo cons and the Trustpilot Apollo 3-star reviews describe the gap and the shrinkage and stop there."
      },
      "workflow": "Inside Apollo, filtering a saved search down to verified emails only before exporting, at the step where the count at the top of the list drops and the remaining names are not enough to fill the week.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "Cleaning a list down to verified-only before a send, when the usable count falls below what the week's activity needs.",
          "cites": ["src:4"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "we do not have 100% of the required information, especially email addresses and phone numbers",
              "cites": ["src:3"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "your total list reduces by like 20%",
              "cites": ["src:4"]
            },
            {
              "situation": "venting",
              "verbatim": "I dont like the absence of results",
              "cites": ["src:3"]
            }
          ],
          "costs_them": "A fifth of the list they built, by the one reviewer who counted it, and the time spent building it back up.",
          "fears": "No source shows the fear; all three quotes stop at what is missing.",
          "dream_outcome": "The filter costs them nothing, because the records that come back already have the email and the phone on them."
        }
      },
      "segments": ["seg:smb"],
      "feature_ref": "feat:data",
      "feature_note": "Apollo Data is the feature this pain tests. One of these two reviewers credits Apollo with not filling the gap with invented data, which is a fair reading of the same complaint from the other side.",
      "cites": ["src:3", "src:4"]
    },
    {
      "id": "pain:credits-gone-mid-month",
      "statement": "The credits run out before the month does, and then the thing I am paying for does nothing.",
      "element": "b2b:ease_of_doing_business:transparency",
      "shape": {
        "surface": "The credit balance hits zero and enriching or exporting stops working.",
        "operational": "Work stops until the cycle turns over or the plan is upgraded, and one reviewer says the number on the plan was never legible enough to plan against in the first place.",
        "personal": null,
        "personal_note": "No source read shows what the stoppage costs the person who hits it. These are owner and buyer reviews about the billing, not rep reviews about the day it happened."
      },
      "workflow": "Inside Apollo, at the point in the billing cycle where an enrich or an export is clicked and the credit balance refuses it, with the upgrade prompt as the only way forward.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "The credit balance reaching zero before the billing period ends.",
          "cites": ["src:4", "src:3"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Apollo charges credits when it is not necessary. It's called nickel and diming.",
              "cites": ["src:3"]
            },
            {
              "situation": "venting",
              "verbatim": "unclear what 40,000 means",
              "cites": ["src:3"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "after your credits are gone is brick tool, you can't use it.",
              "cites": ["src:4"]
            }
          ],
          "costs_them": "The part of the month they paid for and cannot use, plus an upgrade decision made under pressure rather than on a forecast.",
          "fears": "That the metering is designed to run out, which is what the second quote says in as many words.",
          "dream_outcome": "They can tell at the start of the month what the plan will actually let the team do, and the tool still works on the 28th."
        }
      },
      "segments": ["seg:smb"],
      "feature_ref": null,
      "feature_note": "Nothing in the company artifact addresses this. It is a pricing and metering pain, not a product one, and the six listed features all sit on the other side of the credit wall.",
      "cites": ["src:3", "src:4"]
    },
    {
      "id": "pain:auto-renewed-for-another-year",
      "statement": "We said we were done and got rolled into another twelve months anyway.",
      "element": "b2b:ease_of_doing_business:flexibility",
      "shape": {
        "surface": "A renewal they did not agree to, enforced against what they say they were told when they signed.",
        "operational": "They start keeping evidence: one reviewer recorded the sales conversation and sent the transcript back to the vendor, and another describes giving verbal notice and being renewed regardless.",
        "personal": null,
        "personal_note": "No source read shows the personal cost, though the recording behaviour suggests someone expecting to have to defend the decision. That is inference, so the rung stays null. Looked across the 1-star Trustpilot reviews for ZoomInfo and Seamless.AI and the GetApp ZoomInfo cons."
      },
      "workflow": "The renewal notice window on an annual contract, at the step where a cancellation has to be given in writing inside a fixed notice period counted back from a date the buyer does not have in front of them.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "The cancellation notice window closing ahead of an annual renewal date, which reviewers of one vendor describe as a mandatory 60-day notice.",
          "cites": ["src:7", "src:1"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_refusing",
              "verbatim": "When we signed up, we were explicitly told we could cancel at any time.",
              "cites": ["src:1"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "predatory renewal policies",
              "cites": ["src:7"]
            },
            {
              "situation": "venting",
              "verbatim": "to lock businesses into unfavourable terms with no regard for the actual experience or outcome",
              "cites": ["src:5"]
            }
          ],
          "costs_them": "Another annual term on a tool they had already decided against, and the time spent producing evidence of what they were told at signing.",
          "fears": "That the way out is written to be missed, and that being right about the conversation will not matter.",
          "dream_outcome": "They can stop paying the month they stop using it, without a notice window or a negotiation."
        }
      },
      "segments": ["seg:smb", "seg:midmarket"],
      "feature_ref": null,
      "feature_note": "No feature kills this, and none could. It is a commercial-terms pain, and the thing that ends it is a month-to-month or self-serve motion, which is not in the company artifact's feature list at all. The positioning step should know this is the loudest complaint against the incumbents and that the product list has no answer to it.",
      "cites": ["src:1", "src:7", "src:5"]
    },
    {
      "id": "pain:records-rot-in-the-crm",
      "statement": "The enriched records land on top of what we already have and someone has to clean up after them every month.",
      "element": "b2b:ease_of_doing_business:integration",
      "shape": {
        "surface": "Records in the CRM that are out of date, doubled up, or missing the activity that should be attached to them.",
        "operational": "A standing manual maintenance job that one reviewer says is required and is not happening, and a second reviewer describes reconciling call, email and cadence data that has ended up split across systems.",
        "personal": null,
        "personal_note": "No source read shows the personal rung. The AWS Marketplace and GetApp reviews are written in the voice of the function, not the person, and none of them say whose evening it costs."
      },
      "workflow": "The sync from ZoomInfo OperationsOS into the CRM and the marketing automation platform, at the step where an enriched record writes over a record that is already there and the activity history does not follow it.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "A CRM or marketing-automation integration going live, when the enriched records meet the records already in the system for the first time.",
          "cites": ["src:2"]
        }
      ],
      "who_feels": ["technical_evaluator", "end_user"],
      "by_role": {
        "technical_evaluator": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Integration to CRM/marketing automation is a major weak spot for me.",
              "cites": ["src:2"]
            },
            {
              "situation": "venting",
              "verbatim": "Contact database is my biggest concern because it doesn't seem to accurately exclude CRM integrated fields",
              "cites": ["src:2"]
            },
            {
              "situation": "venting",
              "verbatim": "Activity tracking is frustrating because key call, email, and cadence-completion data can be missing or split across systems",
              "cites": ["src:2"]
            }
          ],
          "costs_them": "Ongoing cleanup they own, and a reporting layer they cannot fully trust because the activity behind it is split across systems.",
          "fears": "That the enrichment they bought to fix the database is what keeps breaking it.",
          "dream_outcome": "Enrichment that knows what is already in the CRM, writes only what is new, and brings the activity with it."
        },
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "it required constant maintenance, which doesn't seem to be getting done",
              "cites": ["src:5"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "Looked myself up (while working there) and they had my info from many jobs before.",
              "cites": ["src:1"]
            }
          ],
          "costs_them": "Time spent on records that turn out to be years out of date, discovered one call at a time.",
          "fears": "No source shows the fear; the two quotes stop at the staleness itself.",
          "dream_outcome": "The record in front of them is current enough that they never have to check it against anything else."
        }
      },
      "segments": ["seg:revops", "seg:midmarket"],
      "feature_ref": "feat:waterfall",
      "feature_note": "Waterfall enrichment covers the gap-filling half of this pain. Nothing in the company artifact covers the other half these reviewers name: deduplication against records already in the CRM, and activity that stays attached across systems.",
      "cites": ["src:2", "src:5", "src:6"]
    },
    {
      "id": "pain:mornings-lost-to-list-building",
      "statement": "Half my prospecting time goes on assembling the list rather than on talking to anybody.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "Nothing looks wrong. The list-building is just what the morning is.",
        "operational": "They work it a profile at a time out of LinkedIn with a browser extension, and the reviews that describe this describe it as relief rather than as a complaint, which is the tell that the underlying work is taken for granted.",
        "personal": "Hours disappear into it: one reviewer describes spending hours going in circles inside the tool over contacts she could not save.",
        "personal_note": "One source shows the personal rung directly. It is a single reviewer and it is the reason this pain's confidence is low rather than medium."
      },
      "workflow": "The first hours of the day in LinkedIn with the Apollo Chrome extension open, pulling contact details profile by profile into a list before any calling or sending starts.",
      "type": "latent",
      "confidence": "low",
      "revealed_by": "feat:harness",
      "triggers": [],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "I've spent hours going in circles with this thing.",
              "cites": ["src:3"]
            },
            {
              "situation": "venting",
              "verbatim": "Apollo has made prospecting much faster and easier for me.",
              "cites": ["src:8"]
            }
          ],
          "costs_them": "The part of the day spent before the first conversation, which the second quote values by how much of it a browser extension gave back.",
          "fears": "No source shows the fear. Neither quote treats the list-building as something that could be gone entirely, which is the point of listing this as latent.",
          "dream_outcome": "The list is already built when they sit down, and the morning starts at the first call."
        }
      },
      "segments": ["seg:smb"],
      "feature_ref": "feat:extension",
      "feature_note": "The Chrome extension already removes part of this and both positive reviews are describing that relief. GTM Harness is what would make a buyer call the rest of it a pain, which is why it is in revealed_by rather than here.",
      "cites": ["src:3", "src:8"]
    },
    {
      "id": "pain:throttled-at-volume",
      "statement": "The moment we push real volume, the tool caps what we can send and we are stuck under our own numbers.",
      "element": "b2b:functional:scalability",
      "shape": {
        "surface": "Daily send caps that stop outreach before the day's plan is finished.",
        "operational": "Volume gets rationed across days or split across tools, and one reviewer's summary of the platform is simply that it does not hold up under heavy outbound.",
        "personal": null,
        "personal_note": "No source read shows what the cap costs the individual rep against their number. Both quotes are written about the platform, not about the person's week."
      },
      "workflow": "The daily send in the sequencing tool, at the step where the cadence has more people queued for the day than the plan's daily email cap will release.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "Scaling outbound past what the plan's daily caps allow, which is the point at which both reviewers say the platform stops keeping up.",
          "cites": ["src:9", "src:4"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "The drawbacks I did not enjoy was the limited daily email caps that throttle outreach",
              "cites": ["src:9"]
            },
            {
              "situation": "venting",
              "verbatim": "It doesn't really support heavy outbound usage at scale.",
              "cites": ["src:4"]
            }
          ],
          "costs_them": "Outbound volume they planned for and cannot send, spread across more days than the plan allowed for.",
          "fears": "No source shows the fear; both quotes are flat statements about the ceiling.",
          "dream_outcome": "The volume they plan is the volume that goes out, in one tool, on the day they planned it."
        }
      },
      "segments": ["seg:midmarket"],
      "feature_ref": null,
      "feature_note": "Workspace puts prospecting, outreach and dialing in one place, which is a different problem from the ceiling these two reviewers hit. Nothing in the company artifact speaks to send limits at volume.",
      "cites": ["src:9", "src:4"]
    }
  ],
  "awareness": {
    "default": {
      "level": "solution",
      "rationale": "Across every venue read, buyers write in comparisons: they name two or three data vendors, talk about what they switched from, and evaluate a new one against the one they already have. They know the category exists and have usually already bought in it once.",
      "cites": ["src:4", "src:1", "src:7"]
    },
    "seg:smb": {
      "level": "most_aware",
      "rationale": "Small-business reviewers argue in the language of credit counts, plan tiers and what the thing is worth for a lean team, which is the vocabulary of people who already know the product and the price and are deciding whether to keep paying it.",
      "cites": ["src:3", "src:6"]
    }
  },
  "stats": [
    {
      "id": "stat:value-for-money-gap",
      "stat": "Buyers rate these tools well below what they cost: ZoomInfo Sales sits at 3.5 out of 5 for value for money across 322 GetApp reviews, and Seamless.AI holds a 1.3 out of 5 TrustScore across 310 Trustpilot reviews, with 81% of those ratings at one star.",
      "scope": "Two vendors in the same category, counted on the two review pages read on 2026-09-18: GetApp's ZoomInfo Sales review page (322 reviews, value-for-money sub-score) and Trustpilot's Seamless.AI page (310 reviews, overall TrustScore). These are two different measures on two different populations and should be quoted as two numbers, not averaged. The conservative reading is the GetApp one, since a self-selected Trustpilot page skews to the unhappy.",
      "cites": ["src:5", "src:7"]
    }
  ],
  "keywords": [
    "apollo emails bouncing",
    "b2b contact data accuracy",
    "verified emails only list shrinks",
    "apollo credits ran out",
    "credit nickel and diming sales tool",
    "how to cancel zoominfo auto renewal",
    "zoominfo alternative no annual contract",
    "60 day cancellation notice sales tool",
    "outdated contact data in crm",
    "duplicate records after enrichment",
    "crm data hygiene constant maintenance",
    "daily email caps throttle outreach",
    "heavy outbound at scale",
    "stale job titles contact database",
    "mobile numbers incorrect prospecting"
  ],
  "questions": [
    {
      "id": "q:pains-first-call",
      "question": "On the first call with your last ten customers, which of these did they bring up before you did, and in what words?",
      "why": "Every pain in this map is a hypothesis built from what strangers said about competitors. One customer naming a pain unprompted outranks every review page in here and would move the whole map's confidence.",
      "would_change": "pains[].confidence and the order of pains[]"
    },
    {
      "id": "q:pains-personal-cost",
      "question": "When a customer complains about bad data or a credit wall, what do they say it cost them personally - the evening, the number they missed, the conversation with their manager?",
      "why": "Six of the seven pains have a null personal rung. Public reviews are written about the tool, not about the person, and the personal rung is the one that sells.",
      "would_change": "pains[].shape.personal on every pain except pain:mornings-lost-to-list-building"
    },
    {
      "id": "q:pains-dialer-and-workspace",
      "question": "Do buyers ever name a dialing pain or a too-many-tools pain out loud, and if so in what words? Nothing in the public record I could reach connected either to a specific complaint.",
      "why": "feat:dialer and feat:workspace have no pain pointing at them in this map. I swept a dialer product's review page and the one promising quote there had no visible context on the page, so I could not attribute it. Either buyers do not voice these, or they voice them somewhere I could not fetch.",
      "would_change": "pains[] (a new row per answer) and pains[].feature_ref"
    },
    {
      "id": "q:pains-list-shrink",
      "question": "When your customers turn on verified-only, how much of the list actually goes away?",
      "why": "One reviewer put it at about 20%, which is the only number anyone gave. One source is not a stat, so it is sitting in a pain rather than in stats[], and a real figure from your own data would make it quotable.",
      "would_change": "stats[] (a new row) and pains[].shape.operational on pain:the-record-with-no-number"
    },
    {
      "id": "q:pains-harness-latent",
      "question": "When customers see GTM Harness do the research for them, do they start describing their old list-building mornings as a problem, or do they just take the time back without comment?",
      "why": "pain:mornings-lost-to-list-building is marked latent and low on two thin sources: one frustrated review and one happy one describing the workaround as relief. Whether the agents actually make buyers name it is the whole question, and only you can see that happen.",
      "would_change": "pains[].type, pains[].confidence and pains[].revealed_by on pain:mornings-lost-to-list-building"
    },
    {
      "id": "q:pains-revops-buyer",
      "question": "In a RevOps deal, who actually signs, and does that person describe the CRM cleanup problem the same way the person doing the cleanup does?",
      "why": "The RevOps quotes in pain:records-rot-in-the-crm all come from one review venue and all read as evaluators, not as the person with the budget. Economic buyers rarely post in public, so this gap will not close from the public record.",
      "would_change": "pains[].who_feels and pains[].by_role on pain:records-rot-in-the-crm"
    },
    {
      "id": "q:pains-churn",
      "question": "What did the customers who left in the last year say hurt, and did they name a pain that is not on this map at all?",
      "why": "The map is built from complaints about competitors. A pain that only shows up after someone has been a customer for a year will not appear in any of the sources I could reach, and it is the one most likely to be missing.",
      "would_change": "pains[] (a new row) and pains[].confidence"
    }
  ],
  "sources": [
    {
      "id": "src:1",
      "url": "https://www.trustpilot.com/review/zoominfo.com",
      "title": "ZoomInfo reviews on Trustpilot",
      "venue": "Trustpilot, independent review site, not owned or sponsored by Apollo.io or ZoomInfo. Filtered to 1-2 star reviews.",
      "speaker": "buyer",
      "published": null,
      "pulled": "2026-09-18",
      "verbatim": "Sean R. (Mar 14, 2026, 2 stars): \"Not happy at all with the contact data I got from ZoomInfo. In fact it did me not good at all.\" | Stephan Francis (Mar 15, 2026, 2 stars): \"Outdated and inaccurate! Looked myself up (while working there) and they had my info from many jobs before.\" | Alan Darling (May 20, 2026, 2 stars): \"Difficult company to do business with. Cannot reach anyone for support without making an appointment.\" | Jason (Aug 14, 2026, 2 stars): \"Onboarding is sorely lacking. If you want an Amazon-styled self-service experience, go for it.\" | Bianca Tubolino (1 star): \"When we signed up, we were explicitly told we could cancel at any time. I have this conversation recorded and sent the transcript directly to ZoomInfo. Despite having clear documentation of what was promised, they refuse to honor it.\" | Frank Scotti (Aug 4, 2026, 1 star): \"We tried the platform with eagerness...the data is crap. Not even close to what was promised. Most emails were non deliverable.\""
    },
    {
      "id": "src:2",
      "url": "https://aws.amazon.com/marketplace/reviews/reviews-list/prodview-u52tqtal5ejbu",
      "title": "ZoomInfo reviews on AWS Marketplace",
      "venue": "AWS Marketplace review list, written by customers who bought through the marketplace. Not owned or sponsored by Apollo.io.",
      "speaker": "buyer",
      "published": null,
      "pulled": "2026-09-18",
      "verbatim": "Kyle H. (Sep 11, 2026): \"Contact database is my biggest concern because it doesn't seem to accurately exclude CRM integrated fields\" | Emile L. (Sep 11, 2026): \"We have had major issues with their Websights feature. They promised it would show user level data but rarely, if ever, actually does.\" | Manish D. (Sep 14, 2026): \"Constant updates on micro-events can clutter the dashboard and obstruct high priority buying signals\" | Bobby K. (Sep 13, 2026): \"Activity tracking is frustrating because key call, email, and cadence-completion data can be missing or split across systems\" | Eldon W. (Sep 11, 2026): \"Integration to CRM/marketing automation is a major weak spot for me. Data cleaning/enrichment and real-time reporting also don't meet my needs.\""
    },
    {
      "id": "src:3",
      "url": "https://www.trustpilot.com/review/apollo.io",
      "title": "Apollo.io reviews on Trustpilot",
      "venue": "Trustpilot, independent review site, not owned or sponsored by Apollo.io. Filtered to 1-3 star reviews.",
      "speaker": "buyer",
